import pandas as pd


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"].copy()
    cdc_events = inputs["cdc_events"].copy()
    watermark = inputs["watermark"].copy()

    # Extract watermark high_ts (single row)
    high_ts = watermark["high_ts"].iloc[0]

    # Step 1: keep only events strictly after the watermark
    events = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # Step 2: per product_id, pick the latest event by (event_ts, event_seq)
    if not events.empty:
        events = events.sort_values(
            by=["product_id", "event_ts", "event_seq"],
            ascending=[True, True, True]
        )
        latest_events = events.groupby("product_id", as_index=False).tail(1)
    else:
        latest_events = events

    # Build lookup dict from target_snapshot keyed by product_id
    snapshot_cols = ["product_id", "name", "price", "last_event_ts"]
    snapshot = target_snapshot.set_index("product_id", drop=False)

    result_rows = []

    processed_ids = set()

    # Apply surviving events
    for _, ev in latest_events.iterrows():
        pid = ev["product_id"]
        processed_ids.add(pid)
        op = ev["op"]
        if op == "D":
            # delete: do not add to result
            continue
        else:
            # I or U: upsert name/price, set last_event_ts = event_ts
            result_rows.append({
                "product_id": pid,
                "name": ev["name"],
                "price": ev["price"],
                "last_event_ts": ev["event_ts"],
            })

    # Carry over products without surviving events unchanged
    for pid, row in snapshot.iterrows():
        if pid not in processed_ids:
            result_rows.append({
                "product_id": row["product_id"],
                "name": row["name"],
                "price": row["price"],
                "last_event_ts": row["last_event_ts"],
            })

    new_snapshot = pd.DataFrame(result_rows, columns=snapshot_cols)

    # Ensure dtypes align with target_snapshot where possible
    for col in snapshot_cols:
        if col in target_snapshot.columns:
            try:
                new_snapshot[col] = new_snapshot[col].astype(target_snapshot[col].dtype)
            except (TypeError, ValueError):
                pass

    new_snapshot = new_snapshot.reset_index(drop=True)

    return {"new_snapshot": new_snapshot}
